INSERT INTO public.vector_store (id, content, metadata, embedding) VALUES ('2c1b17ed-ef39-41e6-9e7a-c04dbc7464b8', 'Yorushika《ノーチラス》(Nautilus) 终极隐喻与世界观深度解析
一、 引言：潜水艇与逃避主义的终极浪漫
《ノーチラス》（Nautilus/鹦鹉螺号）是 Yorushika（ヨルシカ）第二张正式录音室专辑《エルマ》（Elma）中的核心曲目。要真正理解这首歌，绝不能仅仅将其视为一首悲伤的流行摇滚。n-buna 在这首歌中植入了极其深厚的文学性，其最核心的意象直接借用了法国作家儒勒·凡尔纳（Jules Verne）的科幻名著《海底两万里》中的潜水艇——“鹦鹉螺号”。

鹦鹉螺号在文学史上是“逃避现实”与“绝对孤独”的极致象征。尼摩船长（Captain Nemo）因为厌恶人类社会的伪善与压迫，选择驾驶这艘潜艇永远潜入深海。而在 Yorushika 的世界观中，男主角艾米（Amy）正是那个在现实世界中对音乐和生活感到绝望的“尼摩船长”，他选择将自己的灵魂沉入名为“鹦鹉螺号”的深海，以此来逃避外界的目光与评价。', '{"author": "Upload", "source": "yorushika.txt", "docName": "yorushika.txt", "sourceType": "FILE"}', '[-0.023363454,0.00075889105,-0.005071442,0.03614596,-0.0027716022,0.0054786177,0.006082361,-0.013299198,-0.0069641066,-0.010519171,0.0115918685,0.04492972,0.0013191085,-0.021094505,0.026710719,-0.007183139,-0.003468013,-0.0036926614,-0.025767196,-0.03996499,-0.0203307,0.008817458,-0.032237075,-0.03657279,-0.018219002,0.0008782356,0.010395614,-0.014343813,-0.029541291,0.03268637,0.03470821,-0.023251131,-0.016051143,0.012299512,0.006969723,-0.008974711,0.04580585,0.03142834,-0.019117596,-0.023565639,-0.020252071,-0.02578966,0.06708007,-0.007829004,0.04144767,0.017522592,-0.032955952,0.005613407,0.012906062,0.05310693,-0.00605428,-0.02906953,0.010637112,-0.010339452,-0.013186873,-0.0055881343,0.0064305663,-0.008705134,-0.019184992,-0.02311634,0.019297315,-0.019578125,-0.031360947,-0.01612977,-0.029676082,-0.0036617722,-0.05818399,0.008351312,0.011827749,-0.019488266,0.0203307,0.009014025,-0.020723835,0.023970006,0.009541949,-0.004751318,-0.013097013,-0.00024921953,0.009553182,0.033674825,-0.008390625,0.0127151115,0.015523219,0.033158135,0.013568776,0.013467684,-0.010378766,0.0041588075,-0.01595005,-0.003417467,-0.029653616,0.0067787715,0.040504143,0.024419304,0.022565952,-0.019061435,0.004046483,-0.017320408,-0.019712916,0.003265829,-0.026081704,0.022734439,0.011249279,0.0065485067,0.0037516318,-0.06281175,-0.013175641,0.029968124,-0.025407758,-0.039762802,0.049242973,-0.00302714,-0.025250504,0.011389684,0.014647089,-0.009772214,0.014456138,0.019151295,0.039493226,-0.027137551,0.04070633,0.027564384,-0.0026578738,-0.006997804,-0.011086409,0.0017017132,0.00903649,0.034213983,0.008851155,-0.028844882,0.0146246245,-0.02810354,0.019791542,-0.0037038939,0.012232116,-0.027631778,-0.04030196,-0.05126481,0